mapper.select:
SELECT DISTINCT s.* 
FROM student s
LEFT JOIN stu_region sr ON s.id = sr.stu_id
LEFT JOIN stu_language sl ON s.id = sl.stu_id
LEFT JOIN stu_certificate sc ON s.id = sc.stu_id
LEFT JOIN stu_internship si ON s.id = si.stu_id


        AND s.id = #{query.id}


        AND s.stu_id = #{query.stuId}


        AND s.name LIKE CONCAT('%', #{query.name}, '%')


        AND s.age = #{query.age}


        AND s.gender = #{query.gender}


        AND s.nation LIKE CONCAT('%', #{query.nation}, '%')


        AND s.major LIKE CONCAT('%', #{query.major}, '%')


        AND s.degree = #{query.degree}


        AND s.graduation_year = #{query.graduationYear}


        AND s.internship >= #{query.internship}


        AND sr.city IN

            #{city}



        AND sr.province IN

            #{province}



        AND s.id IN (
            SELECT stu_id FROM stu_language 
            WHERE language IN 

                #{language}

            GROUP BY stu_id
            HAVING COUNT(DISTINCT language) >= 1
        )


        AND s.id IN (
            SELECT stu_id FROM stu_language 
            WHERE level LIKE CONCAT('%', #{query.languageLevel}, '%')
        )


        AND s.id IN (
            SELECT stu_id FROM stu_certificate 
            WHERE cert_name IN 

                #{certName}

            GROUP BY stu_id
            HAVING COUNT(DISTINCT cert_name) >= 1
        )


        AND s.id IN (
            SELECT stu_id FROM stu_certificate 
            WHERE level LIKE CONCAT('%', #{query.certLevel}, '%')
        )


        AND s.id IN (
            SELECT stu_id FROM stu_internship 
            WHERE company LIKE CONCAT('%', #{query.internshipCompany}, '%')
        )


        AND s.id IN (
            SELECT stu_id FROM stu_speciality 
            WHERE speciality IN 

                #{speciality}

            GROUP BY stu_id
            HAVING COUNT(DISTINCT speciality) >= 1
        )


        AND s.id IN (
            SELECT stu_id FROM stu_job 
            WHERE post IN 

                #{job}

            GROUP BY stu_id
            HAVING COUNT(DISTINCT post) >= 1
        )


ORDER BY s.id
